import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"构建自己的工单 SaaS 后端","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/learn/","contentType":"overview","prev":{"text":"开发者文档","link":"/docs/"},"next":{"text":"01 模块与 HTTP 接口","link":"/learn/module"}},"headers":[],"relativePath":"learn/index.md","filePath":"learn/index.md"}'),d={name:"learn/index.md"};function r(o,t,n,h,l,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="构建自己的工单-saas-后端" tabindex="-1">构建自己的工单 SaaS 后端 <a class="header-anchor" href="#构建自己的工单-saas-后端" aria-label="Permalink to &quot;构建自己的工单 SaaS 后端&quot;">​</a></h1><p>从一条 Rust HTTP 接口开始，把同一个工单模块带到持久化、身份与授权、事务、文件、后台任务、测试和生产部署。全程使用后端接口，不需要写前端。</p><p>工单是读者新增的课程业务，默认应用仍保留知识库参考业务。一次部署服务一个 Organization；工单不是新租户。课程采用自己的资源规则：创建者与当前 Owner/Admin 可访问工单，其他成员看不到它。</p><h2 id="准备与学习顺序" tabindex="-1">准备与学习顺序 <a class="header-anchor" href="#准备与学习顺序" aria-label="Permalink to &quot;准备与学习顺序&quot;">​</a></h2><p>先完成<a href="./../getting-started/quickstart">后端快速开始</a>，准备仓库固定的 Rust、Node、pnpm、just 与 Docker。命令在原模板仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TEMPLATE_ROOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COURSE_ROOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TEMPLATE_ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.scratch/ticket-saas&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tutorial-course.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$COURSE_ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>课程工具在这个独立模板副本接入代码，不注册进原模板默认应用。它为副本分配独立 Compose 项目、卷和空闲端口，将公开请求地址写入 <code>.course.env</code>；后续检查点沿用这些配置。每次升级前停止副本的开发进程，在原模板执行命令，再进入副本运行。自己改过课程文件时先保存差异，避免把检查点更新当作合并工具。</p><table tabindex="0"><thead><tr><th>课</th><th>开发目标</th><th>代码检查点</th></tr></thead><tbody><tr><td><a href="./module">01</a></td><td>模块、Router 与 OpenAPI</td><td><code>module</code></td></tr><tr><td><a href="./migrations">02</a></td><td>自有 schema 与迁移，第一次真实写入</td><td><code>crud</code></td></tr><tr><td><a href="./protocol">03</a></td><td>输入输出、校验与公开错误</td><td>沿用 <code>crud</code></td></tr><tr><td><a href="./authorization">04</a></td><td>Session、有效成员与工单权限</td><td>沿用 <code>crud</code></td></tr><tr><td><a href="./transactions">05</a></td><td>业务与审计共同提交</td><td>沿用 <code>crud</code></td></tr><tr><td><a href="./retries-versions">06</a></td><td>幂等重放与并发版本</td><td>沿用 <code>crud</code></td></tr><tr><td><a href="./files">07</a></td><td>文件上传、核验、发布与下载</td><td><code>files</code></td></tr><tr><td><a href="./jobs">08</a></td><td>JSON 快照导出、Worker 与通知</td><td><code>jobs</code></td></tr><tr><td><a href="./verification">09</a></td><td>HTTP 检查与生成 SDK</td><td>沿用 <code>jobs</code></td></tr><tr><td><a href="./production">10</a></td><td>部署、观测、备份与独立恢复</td><td>沿用 <code>jobs</code></td></tr></tbody></table><p>四个检查点提供完整可运行代码；03–06 在同一份 CRUD 实现上逐项验证责任，不运行一套没有授权的中间业务。完整来源在 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/examples/tutorial-tickets" target="_blank" rel="noreferrer">examples/tutorial-tickets</a>；源码片段与这一份实现共用，不能从零散片段拼出缺少 helper 的应用。</p><h2 id="课程的业务合同" tabindex="-1">课程的业务合同 <a class="header-anchor" href="#课程的业务合同" aria-label="Permalink to &quot;课程的业务合同&quot;">​</a></h2><p>Ticket 有标题、描述、<code>open | closed</code> 状态和整数版本。创建使用 Idempotency-Key；更新携带预期版本。资源授权先于读取、重放和发布。</p><p>附件属于工单，Core Files 拥有对象状态。导出是最多 64 KiB 的 JSON，保存请求时的工单与附件元数据，不包含附件字节或 ZIP。产物业务保留 1 小时；下载与 Worker 发布重新核对身份、成员与资源权限，任务发起 Session 失效后不能发布。</p><p>这些是课程业务的选择，不是 Core 自动提供的工单规则。协议与调用合同以实际 Rust/OpenAPI 为准；章节的验证命令是需要执行的检查，页脚 SHA 只标识构建来源。</p><p>下一步：<a href="./module">新增第一条工单接口</a>。</p><hr><p>源码版本：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/learn/index.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,16)])])}const u=a(d,[["render",r]]);export{k as __pageData,u as default};
